import { RunnerGame, THEMES } from './core.mjs?v=moped-2';
import { GameScene } from './scene.mjs?v=moped-2';
import { ArcadeAudio } from './audio.mjs';

const $=(id)=>document.getElementById(id);
const canvas=$('game-canvas'), shell=$('game-shell'), dialog=$('menu-dialog');
const STORE_KEY='18bro.save.v1';
const skinDefs=[{id:'18bro',name:'18BRO',price:0,color:'#85cd59'},{id:'business',name:'BUSINESS',price:250,color:'#b9c4bd'},{id:'police',name:'POLICE',price:400,color:'#728ccc'},{id:'astronaut',name:'ASTRONAUT',price:650,color:'#d6dfec'},{id:'gold',name:'GOLD',price:1000,color:'#e8c850'},{id:'ceo',name:'CEO 18BRO',price:1500,color:'#e29949'}];
const powerNames={magnet:'COIN MAGNET',moon:'18BRO TO THE MOON',moped:'ELECTRIC MOPED · 1 SHIELD'};
const defaultSave=()=>({highScore:0,totalCoins:0,unlockedSkins:['18bro'],equippedSkin:'18bro',completedMissions:[],settings:{music:false,sfx:true,quality:'sharp',reducedMotion:false},records:[],introSeen:false,totalChips:0,totalPowers:0,runs:0,bestDistance:0,bestChips:0,bestCoins:0,bestDodges:0});
function loadSave(){try{const d=JSON.parse(localStorage.getItem(STORE_KEY));if(!d||typeof d!=='object')return defaultSave();const s={...defaultSave(),...d,settings:{...defaultSave().settings,...d.settings}};for(const k of ['highScore','totalCoins','totalChips','totalPowers','runs','bestDistance','bestChips','bestCoins','bestDodges'])s[k]=Math.max(0,Math.floor(Number(s[k])||0));s.unlockedSkins=Array.isArray(s.unlockedSkins)?s.unlockedSkins.filter(k=>skinDefs.some(x=>x.id===k)):['18bro'];if(!s.unlockedSkins.includes('18bro'))s.unlockedSkins.push('18bro');if(!s.unlockedSkins.includes(s.equippedSkin))s.equippedSkin='18bro';s.records=Array.isArray(s.records)?s.records.filter(r=>r&&Number.isFinite(r.score)&&Number.isFinite(r.distance)).slice(0,8):[];s.completedMissions=Array.isArray(s.completedMissions)?s.completedMissions:[];s.settings.music=false;if(!d.streetEdition)s.settings.quality='sharp';return s;}catch{return defaultSave();}}
let save=loadSave(), storageOK=true, muted=false, practice=false, banked=false, runPowers=0, runId=0, fps=60, toastTime=0,bannerTime=0,hudClock=0,frame=0,themeOverride=null;
const audio=new ArcadeAudio();
const game=new RunnerGame({onEvent:handleEvent});
let scene;
try{scene=new GameScene(canvas)}catch(error){shell.innerHTML='<div class="loading-error"><h2>THE ARCADE COULDN’T START</h2><p>This game needs WebGL. Enable hardware acceleration in your browser, then reload.</p><button onclick="location.reload()">TRY AGAIN</button></div>';throw error;}
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(save));storageOK=true;}catch{storageOK=false;$('footer-note').textContent='SAVE UNAVAILABLE IN THIS BROWSER';}}
function setAudio(){audio.setEnabled(false,save.settings.sfx&&!muted);$('audio-toggle').textContent=muted?'◌':'◖';$('audio-toggle').setAttribute('aria-label',muted?'Unmute sound':'Mute sound');}
function resize(){scene.resize(canvas.clientWidth,canvas.clientHeight,{quality:save.settings.quality});}
function applySettings(){setAudio();document.body.classList.toggle('reduced-motion',save.settings.reducedMotion);resize();}
function toast(text,seconds=2.8){$('toast').textContent=text;toastTime=seconds;$('toast').classList.add('visible');}
function banner(text,seconds=1.6,kind=''){$('run-banner').textContent=text;$('run-banner').className=`run-banner ${kind}`;bannerTime=seconds;}
function syncState(){const state=game.state,menu=state==='MAIN_MENU',over=state==='GAME_OVER',pause=state==='PAUSED';$('main-menu').hidden=!menu;$('character-caption').hidden=!menu;$('hud').hidden=menu||over;$('touch-controls').hidden=state!=='RUNNING';$('pause-panel').hidden=!pause;$('gameover-panel').hidden=!over;shell.classList.toggle('playing',!menu);$('screen-bottom').hidden=!menu;$('screen-status').textContent=menu?'INSERT COIN? NAH. STEAL CHIPS.':practice?'PRACTICE RUN · SAVING OFF':'STAY HUNGRY. STAY AHEAD.';$('location').textContent=menu?'香港 · HONG KONG':game.theme;$('top-best').textContent=String(save.highScore).padStart(6,'0');audio.setMode(menu?'menu':pause?'paused':over?'over':'run');if(pause){$('run-banner').textContent='';$('resume-run').focus({preventScroll:true});}if(menu){bannerTime=0;toastTime=0;$('toast').textContent='';$('toast').classList.remove('visible');}}
function startRun(retry=false){if(dialog.open)dialog.close();audio.unlock();audio.play('confirm');banked=false;runPowers=0;practice=!!(game.debug.invincible||game.debug.speedOverride!==null||game.debug.tierOverride!==null);runId++;game.start({skipIntro:retry});save.introSeen=true;save.introRevision=3;save.streetEdition=true;persist();syncState();if(game.state==='RUNNING')banner('RUN, 18BRO!',1.3);canvas.focus({preventScroll:true});}
const missions=[
{id:'first-run',name:'PETTY SNACK THEFT',description:'Finish your first run.',goal:1,reward:25,value:()=>save.runs},
{id:'distance',name:'OUT OF THE NEIGHBORHOOD',description:'Run 500 meters in a single run.',goal:500,reward:75,value:()=>save.bestDistance},
{id:'street-coins',name:'LOOSE CHANGE',description:'Collect 50 coins in one run.',goal:50,reward:100,value:()=>save.bestCoins},
{id:'powers',name:'CAT WITH BENEFITS',description:'Pick up 5 power-ups across your runs.',goal:5,reward:75,value:()=>save.totalPowers},
{id:'dodges',name:'NINE LIVES',description:'Make 10 close dodges in one run.',goal:10,reward:150,value:()=>save.bestDodges},
{id:'score',name:'LOCAL LEGEND',description:'Score 5,000 points in one run.',goal:5000,reward:200,value:()=>save.highScore}
];
function bankRun(){if(banked||game.time<=0)return {record:false,reward:0};banked=true;if(practice)return {record:false,reward:0};const score=Math.floor(game.score),record=score>save.highScore;save.highScore=Math.max(save.highScore,score);save.totalCoins+=game.coins;save.totalPowers+=runPowers;save.runs++;save.bestDistance=Math.max(save.bestDistance,Math.floor(game.distance));save.bestCoins=Math.max(save.bestCoins,game.coins);save.bestDodges=Math.max(save.bestDodges,game.perfectDodges);save.records.push({score,distance:Math.floor(game.distance),chips:game.chips,coins:game.coins,date:new Date().toISOString()});save.records.sort((a,b)=>b.score-a.score);save.records=save.records.slice(0,8);let reward=0;for(const m of missions){if(m.value()>=m.goal&&!save.completedMissions.includes(m.id)){save.completedMissions.push(m.id);save.totalCoins+=m.reward;reward+=m.reward;}}persist();return {record,reward};}
function showGameOver(){const bank=bankRun();$('result-score').textContent=Math.floor(game.score).toLocaleString();$('result-distance').textContent=`${Math.floor(game.distance).toLocaleString()} m`;$('result-coins').textContent=practice?'PRACTICE':`${game.coins}${bank.reward?' + '+bank.reward+' BONUS':''}`;$('result-best').textContent=save.highScore.toLocaleString();$('new-record').hidden=!bank.record;bannerTime=0;$('run-banner').textContent='';audio.play('gameover');syncState();$('retry-run').focus({preventScroll:true});}
function returnToMenu(){bankRun();game.menu();syncState();$('start-run').focus({preventScroll:true});}
function handleEvent(e){switch(e.type){case 'state':if(scene){syncState();if(e.state==='RUNNING')banner('RUN, 18BRO!',1.2);}break;case 'jump':audio.play('jump');break;case 'slide':audio.play('slide');break;case 'pickup':audio.play(e.kind==='coin'?'coin':'power');break;case 'hit':audio.play('hit');audio.play('whistle');$('hit-flash').classList.remove('hit');void $('hit-flash').offsetWidth;$('hit-flash').classList.add('hit');toast('THEY’RE RIGHT BEHIND YOU! NO MORE MISTAKES.',1.8);break;case 'shieldbreak':audio.play('hit');toast('MOPED SHIELD USED. KEEP RUNNING!',1.8);break;case 'crash':audio.play('hit');audio.play('whistle');bannerTime=0;$('run-banner').textContent='';toastTime=0;$('toast').classList.remove('visible');break;case 'power':if(!e.refresh)runPowers++;banner(powerNames[e.kind],1.8,e.kind==='moon'?'moon':'');break;case 'gameover':showGameOver();break;case 'dodge':if(e.streak%5===0)toast(`CLEAN DODGE ×${e.streak}  +${e.bonus}`,1.4);break;case 'smash':audio.play('hit');break;}}
function updateHUD(){const pow=game.powers;$('hud-score').textContent=String(Math.floor(game.score)).padStart(6,'0');$('hud-distance').textContent=`${Math.floor(game.distance).toLocaleString()} m`;$('hud-coins').textContent=String(game.coins).padStart(2,'0');const badges=[...pow.active.entries()].map(([type,p])=>`<div class="power-badge">${powerNames[type]} · ${Math.ceil(p.remaining)}s</div>`).join('');if($('active-powers').innerHTML!==badges)$('active-powers').innerHTML=badges;if(!$('debug-panel').hidden){const st=scene.stats;$('debug-stats').textContent=`${Math.round(fps)} FPS · LANE ${game.player.lane} · ${Math.floor(game.distance)} m\n${game.state} · ${game.speed.toFixed(1)} u/s\nTIER ${game.tier} · CHUNK ${Math.floor(game.distance/32)}\n${st.drawCalls} DRAWS · ${st.triangles} TRIANGLES\n${game.snapshot().activeEntities} / 256 ENTITIES`;$('debug-stats').style.whiteSpace='pre-line';}audio.setMode(game.state==='PAUSED'?'paused':game.state==='MAIN_MENU'?'menu':game.state==='GAME_OVER'?'over':pow.has('moon')?'moon':'run');}

function drawPortrait(c,id){const ctx=c.getContext('2d');c.width=32;c.height=26;ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,32,26);ctx.fillStyle='#26312a';ctx.fillRect(0,0,32,26);const coat=id==='gold'?'#dfb839':id==='business'?'#9a9d98':'#14151b';ctx.fillStyle=coat;ctx.fillRect(7,7,18,15);ctx.fillRect(5,9,22,10);ctx.fillRect(5,3,6,9);ctx.fillRect(21,3,6,9);ctx.fillStyle='#d36b36';ctx.fillRect(6,5,4,5);ctx.fillStyle='#79b64d';ctx.fillRect(22,5,4,5);ctx.fillStyle=id==='gold'?'#aa852a':id==='police'?'#39547d':'#dedec4';ctx.fillRect(11,3,11,5);ctx.fillStyle=id==='police'?'#223752':'#4f9b46';ctx.fillRect(10,7,14,2);ctx.fillRect(15,4,3,2);ctx.fillStyle='#d6d4c9';ctx.fillRect(9,13,6,4);ctx.fillRect(18,13,6,4);ctx.fillStyle=id==='gold'?'#7c6620':'#252530';ctx.fillRect(12,13,2,3);ctx.fillRect(19,13,2,3);ctx.fillStyle='#d57535';ctx.fillRect(15,17,3,2);ctx.fillStyle=coat;ctx.fillRect(10,21,12,4);if(id==='ceo'){ctx.fillStyle='#dda940';ctx.fillRect(8,12,16,1);ctx.fillRect(12,22,8,1);ctx.fillStyle='#070a0d';ctx.fillRect(8,13,7,4);ctx.fillRect(18,13,7,4);}if(id==='astronaut'){ctx.strokeStyle='#d7d9da';ctx.lineWidth=2;ctx.strokeRect(4,4,24,18);}if(id==='police'){ctx.fillStyle='#375a83';ctx.fillRect(10,22,12,4);}if(id==='business'){ctx.fillStyle='#dde0d8';ctx.fillRect(10,22,12,4);ctx.fillStyle='#ad4440';ctx.fillRect(15,22,2,4);}}
function openPanel(name){audio.unlock();audio.play('confirm');$('panel-kicker').textContent='18BRO / PLAYER SELECT';const titles={characters:'PICK YOUR PARTNER IN CRIME',missions:'A LITTLE EXTRA TROUBLE',records:'THE LOCAL LEGENDS',settings:'MAKE YOURSELF AT HOME',help:'GET CHIPS. GET AWAY.'};$('panel-title').textContent=titles[name]||name;const content=$('panel-content');if(name==='characters'){
content.innerHTML='<div class="skin-grid">'+skinDefs.map(s=>{const owned=save.unlockedSkins.includes(s.id),active=save.equippedSkin===s.id;return `<button class="skin-card ${active?'selected':''}" data-skin="${s.id}" aria-pressed="${active}"><span class="skin-art"><canvas aria-hidden="true" data-portrait="${s.id}"></canvas></span><strong>${s.name}</strong><small>${active?'EQUIPPED':owned?'SELECT':s.price+' COINS'}</small></button>`}).join('')+'</div><div class="wallet"><span>ALL STYLE. SAME NINE LIVES.</span><b>● '+save.totalCoins.toLocaleString()+' COINS</b></div><p>Earn coins on runs to unlock a new look.</p>';
content.querySelectorAll('[data-portrait]').forEach(c=>drawPortrait(c,c.dataset.portrait));content.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{const s=skinDefs.find(s=>s.id===b.dataset.skin);if(!save.unlockedSkins.includes(s.id)){if(save.totalCoins<s.price){toast(`NEED ${s.price-save.totalCoins} MORE COINS`);return}save.totalCoins-=s.price;save.unlockedSkins.push(s.id);}save.equippedSkin=s.id;persist();openPanel('characters');audio.play('confirm');});
}else if(name==='missions'){$('panel-kicker').textContent='SIDE HUSTLES / BONUS COINS';content.innerHTML=missions.map(m=>{const done=save.completedMissions.includes(m.id);return `<div class="mission"><div class="mission-title"><span>${done?'✓ ':''}${m.name}</span><span style="color:#dac963">${done?'COMPLETE':'+'+m.reward+' ●'}</span></div><p>${m.description} <span style="color:#c9d6b7">${Math.min(m.goal,m.value())} / ${m.goal}</span></p><div class="meter"><i style="width:${Math.min(100,m.value()/m.goal*100)}%"></i></div></div>`}).join('')+'<p>Rewards are banked automatically after each run.</p>';
}else if(name==='records'){$('panel-kicker').textContent='LOCAL RECORDS / THIS BROWSER';content.innerHTML=`<p>${save.runs} RUNS · ${save.totalCoins} COINS BANKED · ${save.bestDistance.toLocaleString()} m FARTHEST RUN</p>`+(save.records.length?'<table class="records-table"><thead><tr><th>RANK</th><th>DISTANCE</th><th>COINS</th><th>SCORE</th></tr></thead><tbody>'+save.records.map((r,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${r.distance.toLocaleString()} m</td><td>${r.coins||0}</td><td>${r.score.toLocaleString()}</td></tr>`).join('')+'</tbody></table>':'<p>No legends yet. Take your first run and set the score to beat.</p>');
}else if(name==='settings'){$('panel-kicker').textContent='OPTIONS / SAVED ON THIS BROWSER';content.innerHTML=`<label class="settings-row"><span>SOUND EFFECTS<small>Chips, coins, sirens, chaos</small></span><input type="checkbox" id="setting-sfx" ${save.settings.sfx?'checked':''}></label><label class="settings-row"><span>PICTURE<small>Sharper, detailed polygonal rendering</small></span><select id="setting-quality"><option value="retro">CLASSIC</option><option value="sharp">DETAILED</option><option value="low">PERFORMANCE</option></select></label><label class="settings-row"><span>REDUCED MOTION<small>Less camera shake and idle motion</small></span><input type="checkbox" id="setting-motion" ${save.settings.reducedMotion?'checked':''}></label><p>Controls: arrows or WASD · Space to jump · Esc / P to pause · M to mute. On a phone, swipe or use the on-screen buttons.</p><button id="show-debug" class="secondary-button">DEVELOPER TOOLS <kbd>~</kbd></button>`;$('setting-quality').value=save.settings.quality;[['sfx','sfx'],['motion','reducedMotion']].forEach(([id,key])=>$('setting-'+id).onchange=e=>{save.settings[key]=e.target.checked;muted=false;persist();applySettings();});$('setting-quality').onchange=e=>{save.settings.quality=e.target.value;persist();applySettings();};$('show-debug').onclick=()=>{dialog.close();$('debug-panel').hidden=false;};
}else if(name==='help'){$('panel-kicker').textContent='THE RULES OF PETTY SNACK THEFT';content.innerHTML=`<div class="how-grid"><div class="how-item"><b>01 / DODGE</b><p><kbd>←</kbd> <kbd>→</kbd> or <kbd>A</kbd> <kbd>D</kbd><br>Dodge oncoming cars, carts, and bins.</p></div><div class="how-item"><b>02 / JUMP</b><p><kbd>↑</kbd> <kbd>W</kbd> or <kbd>SPACE</kbd><br>Jump over cars, scooter riders and low barricades. Tall barriers need a lane change.</p></div><div class="how-item"><b>03 / SLIDE</b><p><kbd>↓</kbd> or <kbd>S</kbd><br>Belly-slide below overhead signs.</p></div><div class="how-item"><b>04 / COIN RUN</b><p>Follow the coins through clear lanes. Save them to unlock new outfits.</p></div></div><p>One ordinary hit makes 18Bro stumble and brings both officers close. A second mistake ends the run. A car or scooter collision stops you and leads to immediate capture.</p><p>Oncoming taxis, electric sedans and scooters move faster than the street. The electric moped boosts your speed and absorbs one collision before breaking. The coin magnet pulls in nearby coins; Moon Mode gives a short speed and score boost.</p><p>Phone: swipe in any direction, or tap the arrow buttons. <kbd>ESC</kbd> / <kbd>P</kbd> pauses. <kbd>ENTER</kbd> retries instantly.</p>`;}
if(!dialog.open)dialog.showModal();}

$('start-run').onclick=()=>startRun();$('retry-run').onclick=()=>startRun(true);$('pause-run').onclick=()=>game.pause();$('resume-run').onclick=()=>{audio.unlock();game.resume();canvas.focus({preventScroll:true});};$('over-menu').onclick=returnToMenu;$('pause-menu').onclick=returnToMenu;document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));$('how-to').onclick=()=>{if(['RUNNING','STARTING','CAUGHT'].includes(game.state))game.pause();openPanel('help');};$('close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});$('audio-toggle').onclick=()=>{audio.unlock();muted=!muted;setAudio();};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await shell.requestFullscreen();}catch{toast('FULLSCREEN IS UNAVAILABLE IN THIS BROWSER.');}};
const actions={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'jump',KeyW:'jump',Space:'jump',ArrowDown:'slide',KeyS:'slide'};
window.addEventListener('keydown',e=>{const editing=/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName);if(e.code==='Backquote'&&!editing&&!dialog.open){e.preventDefault();$('debug-panel').hidden=!$('debug-panel').hidden;return;}if(dialog.open||editing)return;if(e.code==='KeyM'){muted=!muted;audio.unlock();setAudio();return;}if(e.code==='Escape'||e.code==='KeyP'){e.preventDefault();if(game.state==='RUNNING'||game.state==='STARTING')game.pause();else if(game.state==='PAUSED'){game.resume();canvas.focus({preventScroll:true});}return;}if(e.code==='Enter'){if(document.activeElement?.tagName==='BUTTON')return;e.preventDefault();if(game.state==='MAIN_MENU'||game.state==='GAME_OVER')startRun(game.state==='GAME_OVER');else if(game.state==='STARTING'){game.start({skipIntro:true});canvas.focus({preventScroll:true});}return;}if(actions[e.code]&&game.state==='RUNNING'){e.preventDefault();if(!e.repeat){audio.unlock();game.input(actions[e.code]);}}});
let swipe=null;canvas.addEventListener('pointerdown',e=>{swipe={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);audio.unlock();});canvas.addEventListener('pointermove',e=>{if(!swipe||e.pointerId!==swipe.id||game.state!=='RUNNING')return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;if(Math.max(Math.abs(dx),Math.abs(dy))<25)return;game.input(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'slide':'jump');swipe=null;});canvas.addEventListener('pointerup',()=>swipe=null);canvas.addEventListener('pointercancel',()=>swipe=null);document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();audio.unlock();game.input(b.dataset.action);canvas.focus({preventScroll:true});}));document.addEventListener('visibilitychange',()=>{if(document.hidden)game.pause();});window.addEventListener('blur',()=>game.pause());window.addEventListener('resize',resize);document.addEventListener('fullscreenchange',()=>{$('fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');resize();});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();game.pause();toast('GRAPHICS PAUSED. RELOAD TO RESTORE THE GAME.',60);});
function markPractice(){practice=true;$('screen-status').textContent='PRACTICE RUN · SAVING OFF';}
$('debug-close').onclick=()=>{$('debug-panel').hidden=true;canvas.focus({preventScroll:true});};$('debug-speed').oninput=e=>{const n=Number(e.target.value);game.debug.speedOverride=n||null;$('debug-speed-label').textContent=n?n+' u/s':'AUTO';markPractice();};$('debug-invincible').onchange=e=>{game.debug.invincible=e.target.checked;markPractice();};$('debug-colliders').onchange=e=>game.debug.showColliders=e.target.checked;$('debug-tier').onchange=e=>{game.debug.tierOverride=Number(e.target.value)||null;markPractice();};$('debug-spawn').onclick=()=>{game.debugSpawn($('debug-type').value);markPractice();canvas.focus({preventScroll:true});};$('debug-activate').onclick=()=>{game.activatePower($('debug-power').value);markPractice();canvas.focus({preventScroll:true});};$('debug-reset').onclick=()=>{game.pause();openPanel('reset');$('panel-title').textContent='RESET THIS SAVE?';$('panel-content').innerHTML='<p>This clears your local records, coins, unlocks, and missions. It cannot be undone.</p><button id="confirm-reset" class="primary-button">RESET SAVE DATA</button><button id="cancel-reset" class="secondary-button">KEEP MY CHIPS</button>';$('cancel-reset').onclick=()=>dialog.close();$('confirm-reset').onclick=()=>{save=defaultSave();persist();applySettings();dialog.close();game.debug={invincible:false,speedOverride:null,tierOverride:null,showColliders:false,themeOverride:null};themeOverride=null;practice=false;banked=true;game.menu();syncState();$('debug-panel').hidden=true;toast('FRESH START. GO GET THOSE CHIPS.');};};

// Optional page tools share the same visible actions and state as keyboard/touch input.
const registry=document.modelContext;
if(registry?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_18bro_run',title:'Read current run',description:'Read the visible 18Bro run score, state and controls.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({ ...game.snapshot(),practice,officerVisible:scene.chaseZ<5&&game.state==='RUNNING',playerHeight:game.player.y,animation:game.player.anim,chasePosition:scene.chaseZ,traffic:game.entities.filter(e=>e.active&&['traffic','scooter','blocker','jump'].includes(e.type)).sort((a,b)=>b.z-a.z).slice(0,8).map(e=>({type:e.type,lane:e.lane,z:e.z,stopped:e.stopped})),officerCount:scene.cops.length,pedestrians:scene.people.length,controls:'Arrows/WASD, Space jump, Esc pause',highScore:save.highScore})},{name:'start_18bro_run',title:'Start a run',description:'Start or retry 18Bro from the main menu or game-over screen.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{if(!['MAIN_MENU','GAME_OVER'].includes(game.state))throw new Error('Return to main menu or finish this run first.');startRun(true);return {state:game.state};}},{name:'control_18bro_run',title:'Control the runner',description:'Perform one visible runner action: change lane, jump, slide, pause or resume.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['left','right','jump','slide','pause','resume']}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!['left','right','jump','slide','pause','resume'].includes(input.action))throw new Error('Unknown runner action.');const a=input.action;if(a==='pause')game.pause();else if(a==='resume')game.resume();else if(!game.input(a))throw new Error('Action unavailable in the current state.');syncState();return {state:game.state,lane:game.player.lane};}}];for(const tool of tools){try{Promise.resolve(registry.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

applySettings();syncState();updateHUD();let last=performance.now();
function loop(now){const raw=(now-last)/1000;last=now;const dt=Math.min(.05,Math.max(0,raw));if(raw>0&&raw<.5)fps=fps*.94+(1/raw)*.06;game.update(dt);scene.render(game,dt,{skin:save.equippedSkin,menu:game.state==='MAIN_MENU',reducedMotion:save.settings.reducedMotion});audio.update(dt);if(toastTime>0){toastTime-=dt;if(toastTime<=0){$('toast').classList.remove('visible');$('toast').textContent='';}}if(bannerTime>0){bannerTime-=dt;if(bannerTime<=0)$('run-banner').textContent='';}if(game.state==='STARTING'){$('run-banner').textContent=game.introProgress<.27?'JUST ONE BAG…':game.introRemaining<1?'RUN, 18BRO!':'THE SNACK HEIST';$('screen-status').textContent='ENTER TO SKIP';}hudClock+=dt;if(hudClock>.09){updateHUD();hudClock=0;}frame++;requestAnimationFrame(loop);}
